        static let page: UInt8 = 0x0A
        /// Capability header and component type table. GET.
        static let CAPS = VendorCommand(0x0A10)
        /// Descriptor of one noun. GET.
        static let NOUN_DESC = VendorCommand(0x0A11)
        /// Last deferred result, dirty flag, per-slot and IR status. GET.
        static let STATUS = VendorCommand(0x0A12)
        /// Group and macro limits, validity and the running macro. GET.
        static let EXT_STATUS = VendorCommand(0x0A13)
        /// Persist the whole live configuration. SET.
        static let SAVE = VendorCommand(0x0A18)
        /// Discard the live preview and re-apply the stored configuration. SET.
        static let REVERT = VendorCommand(0x0A19)
        /// One binding, live preview. GET and SET.
        static let BINDING = VendorCommand(0x0A20)
        /// Slot name, NUL padded; a single NUL clears it. GET and SET.
        static let SLOT_NAME = VendorCommand(0x0A21)
        /// Pins a binding of one type in one slot could take: status, flags, generation, masks, shareable. GET.
        static let BINDING_PIN_AVAIL = VendorCommand(0x0A22)
        /// One IR command, live preview. GET and SET.
        static let IR_CMD = VendorCommand(0x0A30)
        /// Learn state, protocol and the last learned code. GET.
        static let IR_LEARN_STATUS = VendorCommand(0x0A31)
        /// Arm IR learn on the live receiver. SET.
        static let IR_LEARN_ARM = VendorCommand(0x0A32)
        /// Cancel IR learn. SET.
        static let IR_LEARN_CANCEL = VendorCommand(0x0A33)
        /// One target group, live preview. GET and SET.
        static let GROUP = VendorCommand(0x0A40)
        /// Whole macro: header and every step. GET.
        static let MACRO = VendorCommand(0x0A50)
        /// Macro name and step count. GET and SET.
        static let MACRO_HEADER = VendorCommand(0x0A51)
        /// One macro step, address (step << 8) | macro. GET and SET.
        static let MACRO_STEP = VendorCommand(0x0A52)
        /// Run a macro; an empty macro is a no-op. SET.
        static let MACRO_FIRE = VendorCommand(0x0A58)
        /// Stop the running macro. SET.
        static let MACRO_CANCEL = VendorCommand(0x0A59)
        /// Aux output on or off. GET and SET.
        static let AUX_STATE = VendorCommand(0x0A60)
        /// Aux PWM level, 8.8 percent, clamped to 100. GET and SET.
        static let AUX_LEVEL = VendorCommand(0x0A61)
        /// 16 state bytes then 16 levels; non-aux slots read zero. GET.
        static let AUX_ALL = VendorCommand(0x0A62)
        /// Display mode, timing, brightness and flags. GET and SET.
        static let DISPLAY_CONFIG = VendorCommand(0x0A70)
        /// Display page count and model count. GET.
        static let DISPLAY_CAPS = VendorCommand(0x0A71)
        /// One display page; all zero is empty. GET and SET.
        static let DISPLAY_PAGE = VendorCommand(0x0A72)
        /// Link state, shown page, live model and I2C NAK count. GET.
        static let DISPLAY_STATUS = VendorCommand(0x0A73)
    }

    /// UART and I2C control transports.
    enum XPORT {
        static let page: UInt8 = 0x0B
        /// Stored UART control config; the apply result is in STATUS. GET and SET.
        static let UART_CONFIG = VendorCommand(0x0B10)
        /// Stored I2C target control config; the apply result is in STATUS. GET and SET.
        static let I2C_CONFIG = VendorCommand(0x0B11)
        /// Last apply result and live state of each control transport. GET.
        static let STATUS = VendorCommand(0x0B12)
        /// UART TX and RX pins by instance: status, flags, generation, valid and free masks. GET.
        static let UART_PIN_AVAIL = VendorCommand(0x0B13)
        /// I2C SDA and SCL pins by instance: status, flags, generation, valid and free masks. GET.
        static let I2C_PIN_AVAIL = VendorCommand(0x0B14)
    }

    /// I2S clock pins and modes, MCK.
    enum CLOCK {
        static let page: UInt8 = 0x0C
        /// BCK GPIO of role 0 master or unified, 1 slave (LRCLK is BCK + 1); 0xFF restores the default. GET and SET.
        static let I2S_BCK_PIN = VendorCommand(0x0C10)
        /// 0 one clock pair for both modes, 1 a separate slave pair. GET and SET.
        static let I2S_CLOCK_PIN_MODE = VendorCommand(0x0C11)
        /// I2S clock mode, 0 master or 1 slave. GET and SET.
        static let I2S_CLOCK_MODE = VendorCommand(0x0C12)
        /// I2S slave clock lock state and measured rate. GET.
        static let I2S_SLAVE_STATUS = VendorCommand(0x0C13)
        /// BCK pins one clock pair could take (LRCLK is BCK + 1): status, flags, generation, valid and free masks. GET.
        static let I2S_BCK_PIN_AVAIL = VendorCommand(0x0C14)
        /// MCK output enable. GET and SET.
        static let MCK_ENABLE = VendorCommand(0x0C20)
        /// MCK GPIO, a clk_gpout pin; 0xFF restores the default. GET and SET.
        static let MCK_PIN = VendorCommand(0x0C21)
        /// MCK multiplier, 0 for 128x or 1 for 256x. GET and SET.
        static let MCK_MULTIPLIER = VendorCommand(0x0C22)
        /// Pins MCK could take: status, flags, generation, valid and free masks. GET.
        static let MCK_PIN_AVAIL = VendorCommand(0x0C23)
    }

    /// Bench and diagnostic commands with no stability promise.
    enum DIAG {
        static let page: UInt8 = 0xF0
        /// Latest 1 Hz ClockDiagPacket snapshot. GET, DSPI_CLOCK_DIAG builds only.
        static let CLOCK_DIAG = VendorCommand(0xF010)
        /// Loopback capture overflow and underrun frame counts. GET, DSPI_LOOPBACK builds only.
        static let LOOPBACK_STATS = VendorCommand(0xF020)
        /// Worst time of main-loop section wValue (LOOP_PROF_SECTION_LIST). GET, DSPI_LOOP_PROF builds only.
        static let LOOP_PROF_SECTION = VendorCommand(0xF030)
        /// Worst step of background job wValue (BG_JOB_LIST). GET, DSPI_LOOP_PROF builds only.
        static let LOOP_PROF_JOB = VendorCommand(0xF031)
        /// Worst handler time of paged command wValue, GET and SET together. GET, DSPI_LOOP_PROF builds only.
        static let LOOP_PROF_COMMAND = VendorCommand(0xF032)
        /// Background pacing n: above 1, one unit per step on one pass in n; 0 sets 1. GET and SET, DSPI_LOOP_PROF builds only.
        static let LOOP_PROF_BG_PACE = VendorCommand(0xF033)
        /// Zero every section, job and command worst time. SET, DSPI_LOOP_PROF builds only.
        static let LOOP_PROF_RESET = VendorCommand(0xF034)
    }
}

